package no.aktivkommune.masterdatabase.dto;

import io.swagger.v3.oas.annotations.media.Schema;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;

// Body for create (POST). No id: it is generated by the database.
public record KommuneCreate(

	@Schema(description = "Kommune number, exactly 4 digits", example = "4601")
	@NotBlank @Pattern(regexp = "[0-9]{4}", message = "kommunenr must be 4 digits")
	String kommunenr,

	@Schema(description = "Kommune name", example = "Bergen")
	@NotBlank
	String navn,

	@Schema(description = "County name. Optional; null when left out.", example = "Vestland")
	String fylkesnavn,

	@Schema(description = "Base URL of the kommune's Aktiv kommune booking system. Required. The booking system is "
			+ "registered (active) in the same call, and the next nightly sync loads the kommune's data from it. "
			+ "Must be https://<name>.aktiv-kommune.no.",
			example = "https://bergen.aktiv-kommune.no")
	@NotBlank @Pattern(regexp = AktivKommuneUrl.REGEX, flags = Pattern.Flag.CASE_INSENSITIVE,
			message = "bookingBaseUrl must be https://<name>.aktiv-kommune.no")
	String bookingBaseUrl
)
{
}
